using NeutronStar.ReactorBench.Domain;
static void Check(bool b){if(!b)throw new Exception("Reducer contract assertion");}
var flow=Reducers.Flow(new Flow(),new Loaded());flow=Reducers.Flow(flow,new Start("encrypt",2));flow=Reducers.Flow(flow,new Advance(2,1000));Check(flow.Progress==50);Check(Reducers.Flow(flow,new Advance(1,2000))==flow);flow=Reducers.Flow(flow,new Cancel());Check(flow.Status=="canceled");Check(Reducers.Flow(flow,new Advance(2,2000))==flow);flow=Reducers.Flow(flow,new Reset());Check(flow.Progress==0);flow=Reducers.Flow(flow,new Start("decrypt",3));Check(Reducers.Flow(flow,new Advance(3,2000)).Status=="success");
var rows=Reducers.List(Rows.Empty,new Replace(1000));rows=Reducers.List(rows,new Replace(10000));Check(rows.Items[0].Id==1000);rows=Reducers.List(rows,new Replace(1000));rows=Reducers.List(rows,new Reverse());Check(rows.Items[0].Id==11999);rows=Reducers.List(rows,new Splice());Check(rows.Items[0].Id==12000);var old=rows.Items[0];rows=Reducers.List(rows,new Update());Check(rows.Tick==1&&old.Value==0);Check(Reducers.Visible(Reducers.List(rows,new Query("row-12000 "))).Length==1);rows=Reducers.List(rows,new Remount());Check(rows.Items[0].Id==0&&rows.Tick==0);rows=Reducers.List(rows,new BeginBurst(5));rows=Reducers.List(rows,new Stop());Check(Reducers.List(rows,new Update(5))==rows);Console.WriteLine("PASS independent Reactor reducers and stale-token assertions");
